	return (
		<header
			className={cn(
				WINDOW_MANAGER_DRAG_HANDLE_CLASS,
				'border-base-300 bg-base-200/80 flex h-10 shrink-0 cursor-default touch-none items-center gap-2 border-b px-1.5 select-none',
