			className={cn(
				'flex min-h-8 cursor-default items-center gap-2 rounded-sm px-2 text-sm outline-none select-none',
				'data-[highlighted]:bg-base-200 data-[disabled]:pointer-events-none data-[disabled]:opacity-40',
				className,
			)}
			{...props}
		/>
	);
}

