const windowControlClassName = cn(
	'hover:bg-base-300/80 grid size-8 place-items-center disabled:pointer-events-none disabled:opacity-35',
	'focus-visible:ring-primary focus-visible:z-10 focus-visible:ring-2 focus-visible:outline-none',
);

'use client';

import { Menu as BaseMenu } from '@base-ui/react/menu';
import {
	AppWindow,
	Focus,
	LockKeyhole,
	LogIn,
	LogOut,
	Minus,
	PanelsTopLeft,
	UserRound,
	UserRoundCog,
	X,
} from 'lucide-react';
import type { ComponentPropsWithRef, ReactNode } from 'react';
import { useShallow } from 'zustand/react/shallow';
import { cn } from '@/lib/utils';
import { WindowManagerMenuItem, WindowManagerMenuSeparator } from './window-manager-chrome';
import { useWindowManager } from './window-manager-context';
import type { ManagedWindow, WindowManagerActions, WindowManagerDockPosition } from './window-manager-types';

export const WINDOW_MANAGER_DOCK_Z_INDEX = 9_000;

export type WindowManagerDockItemRenderContext = {
	active: boolean;
	icon: ReactNode;
	minimized: boolean;
	win: ManagedWindow;
};

export type WindowManagerDockUser = {
	avatarUrl?: string;
	displayName?: string;
	hasNotification?: boolean;
	initials?: string;
	loginName?: string;
	onLock?: () => void;
	onOpenProfile?: () => void;
	onSignIn?: () => void;
	onSignOut?: () => void;
};

export type WindowManagerDockUserMenuRenderContext = {
	user: WindowManagerDockUser;
};

export type WindowManagerDockProps = ComponentPropsWithRef<'nav'> & {
	menuZIndex?: number;
	minimizeActiveOnClick?: boolean;
	renderIcon?: (win: ManagedWindow) => ReactNode;
	renderItem?: (context: WindowManagerDockItemRenderContext) => ReactNode;
	renderUserMenuItems?: (context: WindowManagerDockUserMenuRenderContext) => ReactNode;
	showActions?: boolean;
	user?: WindowManagerDockUser;
};

export function WindowManagerDock({
	className,
	menuZIndex = WINDOW_MANAGER_DOCK_Z_INDEX + 1,
	minimizeActiveOnClick = true,
	renderIcon = defaultWindowIcon,
	renderItem,
	renderUserMenuItems,
	showActions = true,
	style,
	user,
	...props
}: WindowManagerDockProps) {
	const { actions, activeId, dock, dockOrder, fullscreen, windowById } = useWindowManager(
		useShallow((state) => ({
			actions: state.actions,
			activeId: state.activeId,
			dock: state.workspace.dock,
			dockOrder: state.dockOrder,
			fullscreen: state.order.some((id) => state.windows[id]?.mode === 'fullscreen'),
			windowById: state.windows,
		})),
	);
	if (!dock.visible || fullscreen) return null;
	const windows = dockOrder.flatMap((id) => {
		const win = windowById[id];
		return win?.showInDock ? [win] : [];
	});
	const managedWindows = Object.values(windowById);
	const vertical = dock.position !== 'bottom';
	const dockStyle = vertical ? { width: dock.size } : { height: dock.size };

	return (
		<nav
			aria-label='窗口停靠栏'
			data-position={dock.position}
			className={cn(
				'border-base-300 bg-base-100/95 absolute flex items-center border shadow-lg backdrop-blur',
				dock.position === 'bottom' && 'inset-x-0 bottom-0 flex-row px-2',
				dock.position === 'left' && 'inset-y-0 left-0 flex-col py-2',
				dock.position === 'right' && 'inset-y-0 right-0 flex-col py-2',
				className,
			)}
			style={{ zIndex: WINDOW_MANAGER_DOCK_Z_INDEX, ...dockStyle, ...style }}
			{...props}
		>
			{user ? (
				<WindowManagerDockUserAvatar
					menuItems={renderUserMenuItems?.({ user })}
					position={dock.position}
					user={user}
					zIndex={menuZIndex}
				/>
			) : null}
			{showActions ? (
				<WindowManagerDockMenu
					actions={actions}
					active={activeId ? windowById[activeId] : undefined}
					canCloseAny={managedWindows.some((win) => win.capabilities.close)}
					canMinimizeAny={managedWindows.some((win) => win.mode !== 'minimized' && win.capabilities.minimize)}
					count={managedWindows.length}
					position={dock.position}
					zIndex={menuZIndex}
				/>
			) : null}
			<div
				className={cn(
					'flex min-h-0 min-w-0 flex-1 items-center gap-1 overflow-auto',
					vertical ? 'flex-col px-1 py-2' : 'flex-row px-2 py-1',
				)}
			>
				{windows.map((win) => {
					const active = activeId === win.id && win.mode !== 'minimized';
					const icon = renderIcon(win);
					const context = { active, minimized: win.mode === 'minimized', icon, win };
					return (
						<button
							key={win.id}
							type='button'
							aria-label={`${win.title}${win.mode === 'minimized' ? '，已最小化' : ''}`}
							aria-pressed={active}
							title={win.title}
							data-active={active || undefined}
							data-mode={win.mode}
							className={cn(
								'hover:bg-base-200 relative grid size-9 shrink-0 place-items-center rounded-sm',
								'focus-visible:ring-primary focus-visible:ring-2 focus-visible:outline-none',
								'data-[active=true]:bg-primary/12 data-[active=true]:text-primary',
								'data-[mode=minimized]:opacity-55',
							)}
							onClick={() => {
								if (win.mode === 'minimized') actions.restore(win.id);
								else if (active && minimizeActiveOnClick) actions.minimize(win.id);
								else actions.focus(win.id);
							}}
						>
							{renderItem ? renderItem(context) : icon}
							<span
								aria-hidden='true'
								className={cn(
									'bg-primary absolute rounded-full opacity-0 data-[active=true]:opacity-100',
									vertical ? 'top-1 bottom-1 left-0 w-0.5' : 'inset-x-1 bottom-0 h-0.5',
								)}
								data-active={active || undefined}
							/>
						</button>
					);
				})}
				{windows.length === 0 ? <AppWindow aria-hidden='true' className='text-base-content/30 size-4' /> : null}
			</div>
		</nav>
	);
}

type WindowManagerDockUserAvatarProps = {
	menuItems?: ReactNode;
	position: WindowManagerDockPosition;
	user: WindowManagerDockUser;
	zIndex: number;
};

function WindowManagerDockUserAvatar({ menuItems, position, user, zIndex }: WindowManagerDockUserAvatarProps) {
	const { avatarUrl, displayName, hasNotification, loginName, onLock, onOpenProfile, onSignIn, onSignOut } = user;
	const normalizedAvatarUrl = avatarUrl?.trim();
	const normalizedDisplayName = displayName?.trim();
	const normalizedLoginName = loginName?.trim();
	const normalizedInitials = user.initials?.trim();
	const hasIdentity = Boolean(
		normalizedAvatarUrl || normalizedDisplayName || normalizedLoginName || normalizedInitials,
	);
	if (!hasIdentity) {
		if (!onSignIn) return null;
		return (
			<button
				type='button'
				aria-label='登录'
				title='未登录'
				disabled={!onSignIn}
				className='hover:bg-base-200 focus-visible:ring-primary grid size-9 shrink-0 place-items-center rounded-full focus-visible:ring-2 focus-visible:outline-none disabled:opacity-40'
				onClick={onSignIn}
			>
				<LogIn className='size-4' />
			</button>
		);
	}

	const side = getWindowManagerDockMenuSide(position);
	const initials = resolveUserInitials(user);
	const label = normalizedDisplayName || normalizedLoginName || '账户';
	const hasPrimaryActions = Boolean(onOpenProfile || onLock || menuItems);
	return (
		<BaseMenu.Root>
			<BaseMenu.Trigger
				aria-label={`账户菜单${hasNotification ? '，有新通知' : ''}`}
				title={label}
				className='ring-base-300 hover:ring-primary focus-visible:ring-primary relative grid size-9 shrink-0 place-items-center rounded-full ring-1 outline-none focus-visible:ring-2'
			>
				<span className='bg-primary/12 text-primary relative grid size-9 place-items-center rounded-full text-sm font-semibold'>
					{initials || <UserRound className='size-4' />}
					{normalizedAvatarUrl ? (
						<img
							alt={`${label}头像`}
							className='absolute inset-0 size-9 rounded-full object-cover'
							loading='lazy'
							referrerPolicy='no-referrer'
							src={normalizedAvatarUrl}
							onError={(event) => {
								event.currentTarget.hidden = true;
							}}
						/>
					) : null}
				</span>
				{hasNotification ? (
					<span
						aria-hidden='true'
						className='bg-error ring-base-100 absolute top-0 right-0 size-2.5 rounded-full ring-2'
					/>
				) : null}
			</BaseMenu.Trigger>
			<BaseMenu.Portal>
				<BaseMenu.Positioner align='start' side={side} sideOffset={8} className='outline-none' style={{ zIndex }}>
					<BaseMenu.Popup className='border-base-300 bg-base-100 text-base-content min-w-52 rounded-md border p-1 shadow-xl outline-none'>
						<div className='px-2 py-2'>
							<div className='truncate text-sm font-medium'>{label}</div>
							{normalizedLoginName ? (
								<div className='text-base-content/55 truncate text-xs'>@{normalizedLoginName}</div>
							) : null}
						</div>
						{hasPrimaryActions || onSignOut ? <WindowManagerMenuSeparator /> : null}
						{hasPrimaryActions ? (
							<BaseMenu.Group>
								{onOpenProfile ? (
									<WindowManagerMenuItem onClick={onOpenProfile}>
										<UserRoundCog className='size-4' />
										<span>个人资料</span>
									</WindowManagerMenuItem>
								) : null}
								{onLock ? (
									<WindowManagerMenuItem onClick={onLock}>
										<LockKeyhole className='size-4' />
										<span>锁定</span>
									</WindowManagerMenuItem>
								) : null}
								{menuItems}
							</BaseMenu.Group>
						) : null}
						{onSignOut ? (
							<>
								{hasPrimaryActions ? <WindowManagerMenuSeparator /> : null}
								<WindowManagerMenuItem className='text-error' onClick={onSignOut}>
									<LogOut className='size-4' />
									<span>退出登录</span>
								</WindowManagerMenuItem>
							</>
						) : null}
					</BaseMenu.Popup>
				</BaseMenu.Positioner>
			</BaseMenu.Portal>
		</BaseMenu.Root>
	);
}

type WindowManagerDockMenuProps = {
	actions: WindowManagerActions;
	active?: ManagedWindow;
	canCloseAny: boolean;
	canMinimizeAny: boolean;
	count: number;
	position: WindowManagerDockPosition;
	zIndex: number;
};

function WindowManagerDockMenu({
	actions,
	active,
	canCloseAny,
	canMinimizeAny,
	count,
	position,
	zIndex,
}: WindowManagerDockMenuProps) {
	const side = getWindowManagerDockMenuSide(position);
	return (
		<BaseMenu.Root>
			<BaseMenu.Trigger
				aria-label='窗口管理'
				title='窗口管理'
				className='hover:bg-base-200 focus-visible:ring-primary grid size-8 shrink-0 place-items-center rounded-sm focus-visible:ring-2 focus-visible:outline-none'
			>
				<PanelsTopLeft className='size-4' />
			</BaseMenu.Trigger>
			<BaseMenu.Portal>
				<BaseMenu.Positioner align='start' side={side} sideOffset={6} className='outline-none' style={{ zIndex }}>
					<BaseMenu.Popup className='border-base-300 bg-base-100 text-base-content min-w-48 rounded-md border p-1 shadow-xl outline-none'>
						<BaseMenu.Group>
							<BaseMenu.GroupLabel className='text-base-content/55 px-2 py-1 text-xs'>当前窗口</BaseMenu.GroupLabel>
							<WindowManagerMenuItem
								disabled={!active || active.mode !== 'normal' || !active.capabilities.move}
								onClick={() => active && actions.center(active.id)}
							>
								<Focus className='size-4' />
								<span>窗口居中</span>
							</WindowManagerMenuItem>
							<WindowManagerMenuItem
								disabled={!active?.capabilities.close}
								onClick={() => active && actions.close(active.id)}
							>
								<X className='size-4' />
								<span>关闭当前窗口</span>
							</WindowManagerMenuItem>
						</BaseMenu.Group>
						<WindowManagerMenuSeparator />
						<BaseMenu.Group>
							<BaseMenu.GroupLabel className='text-base-content/55 px-2 py-1 text-xs'>
								窗口管理 ({count})
							</BaseMenu.GroupLabel>
							<WindowManagerMenuItem disabled={!canMinimizeAny} onClick={actions.minimizeAll}>
								<Minus className='size-4' />
								<span>最小化所有窗口</span>
							</WindowManagerMenuItem>
							<WindowManagerMenuItem disabled={!canCloseAny} onClick={actions.closeAll}>
								<X className='size-4' />
								<span>关闭所有窗口</span>
							</WindowManagerMenuItem>
						</BaseMenu.Group>
					</BaseMenu.Popup>
				</BaseMenu.Positioner>
			</BaseMenu.Portal>
		</BaseMenu.Root>
	);
}

function getWindowManagerDockMenuSide(position: WindowManagerDockPosition) {
	return position === 'right' ? 'left' : position === 'left' ? 'right' : 'top';
}

function resolveUserInitials(user: WindowManagerDockUser) {
	const value = user.initials?.trim() || user.displayName?.trim() || user.loginName?.trim() || '';
	const graphemes =
		typeof Intl.Segmenter === 'function'
			? Array.from(new Intl.Segmenter(undefined, { granularity: 'grapheme' }).segment(value), ({ segment }) => segment)
			: Array.from(value);
	return graphemes.slice(0, 2).join('').toUpperCase();
}

function defaultWindowIcon(win: ManagedWindow) {
	return win.icon ? (
		<span className='max-w-7 truncate text-xs font-semibold'>{win.icon}</span>
	) : (
		<span className='text-xs font-semibold'>{win.title.trim().slice(0, 1).toUpperCase() || 'W'}</span>
	);
}

'use client';

import { Resizable, type ResizeDirection } from 're-resizable';
import {
	type CSSProperties,
	type ReactNode,
	type PointerEvent as ReactPointerEvent,
	useEffect,
	useRef,
	useState,
} from 'react';

export type WindowManagerMotionBounds = {
	height: number;
	width: number;
	x: number;
	y: number;
};

export type WindowManagerMotionSurfaceProps = {
	cancel?: string;
	children: ReactNode;
	disableDragging?: boolean;
	dragHandleClassName?: string;
	enableResizing?: boolean;
	interactionKey?: string | number;
	maxHeight: number;
	maxWidth: number;
	minHeight: number;
	minWidth: number;
	movementBounds: WindowManagerMotionBounds;
	onMoveStart?: () => void;
	onMoveStop?: (position: { x: number; y: number }) => void;
	onResizeStart?: () => void;
	onResizeStop?: (value: WindowManagerMotionBounds) => void;
	position: { x: number; y: number };
	size: { height: number; width: number };
	style?: CSSProperties;
};

type DragSession = {
	maxX: number;
	maxY: number;
	minX: number;
	minY: number;
	originX: number;
	originY: number;
	pointerId: number;
	startX: number;
	startY: number;
};

export function WindowManagerMotionSurface({
	cancel,
	children,
	disableDragging = false,
	dragHandleClassName,
	enableResizing = true,
	interactionKey = 'default',
	maxHeight,
	maxWidth,
	minHeight,
	minWidth,
	movementBounds,
	onMoveStart,
	onMoveStop,
	onResizeStart,
	onResizeStop,
	position,
	size,
	style,
}: WindowManagerMotionSurfaceProps) {
	const nodeRef = useRef<HTMLDivElement | null>(null);
	const activity = useRef<'drag' | 'resize' | undefined>(undefined);
	const dragSession = useRef<DragSession | undefined>(undefined);
	const latestPosition = useRef(position);
	const previousInteractionKey = useRef(interactionKey);
	const resizeOrigin = useRef<WindowManagerMotionBounds>({ ...position, ...size });
	const [visualPosition, setVisualPosition] = useState(position);
	const [visualSize, setVisualSize] = useState(size);

	useEffect(() => {
		if (previousInteractionKey.current === interactionKey) return;
		previousInteractionKey.current = interactionKey;
		const pointerId = dragSession.current?.pointerId;
		dragSession.current = undefined;
		activity.current = undefined;
		if (pointerId !== undefined && nodeRef.current?.hasPointerCapture(pointerId)) {
			nodeRef.current.releasePointerCapture(pointerId);
		}
		latestPosition.current = position;
		setVisualPosition(position);
		setVisualSize(size);
	}, [interactionKey, position, size]);
	useEffect(() => {
		if (activity.current) return;
		latestPosition.current = position;
		setVisualPosition(position);
	}, [position]);
	useEffect(() => {
		if (!activity.current) setVisualSize(size);
	}, [size]);

	const startDrag = (event: ReactPointerEvent<HTMLDivElement>) => {
		if (disableDragging || event.button !== 0 || !nodeRef.current) return;
		const target = event.target instanceof Element ? event.target : undefined;
		if (!target) return;
		if (dragHandleClassName && !target.closest(`.${dragHandleClassName}`)) return;
		if (cancel && target.closest(cancel)) return;
		event.preventDefault();
		nodeRef.current.setPointerCapture(event.pointerId);
		dragSession.current = {
			pointerId: event.pointerId,
			startX: event.clientX,
			startY: event.clientY,
			originX: visualPosition.x,
			originY: visualPosition.y,
			minX: movementBounds.x,
			minY: movementBounds.y,
			maxX: Math.max(movementBounds.x, movementBounds.x + movementBounds.width - visualSize.width),
			maxY: Math.max(movementBounds.y, movementBounds.y + movementBounds.height - visualSize.height),
		};
		activity.current = 'drag';
		onMoveStart?.();
	};

	const moveDrag = (event: ReactPointerEvent<HTMLDivElement>) => {
		const session = dragSession.current;
		if (!session || session.pointerId !== event.pointerId) return;
		const next = getWindowManagerDragPosition(session, { x: event.clientX, y: event.clientY });
		latestPosition.current = next;
		setVisualPosition(next);
	};

	const stopDrag = (event: ReactPointerEvent<HTMLDivElement>) => {
		const session = dragSession.current;
		if (!session || session.pointerId !== event.pointerId) return;
		dragSession.current = undefined;
		activity.current = undefined;
		if (nodeRef.current?.hasPointerCapture(event.pointerId)) nodeRef.current.releasePointerCapture(event.pointerId);
		onMoveStop?.(latestPosition.current);
	};

	const constrainResize = (direction: ResizeDirection, requested: { height: number; width: number }) =>
		getWindowManagerConstrainedResize({
			bounds: movementBounds,
			direction,
			maxHeight,
			maxWidth,
			minHeight,
			minWidth,
			origin: resizeOrigin.current,
			requested,
		});

	return (
		<div
			ref={nodeRef}
			style={{
				position: 'absolute',
				width: visualSize.width,
				height: visualSize.height,
				transform: `translate(${visualPosition.x}px, ${visualPosition.y}px)`,
				...style,
			}}
			onPointerCancel={stopDrag}
			onPointerDown={startDrag}
			onPointerMove={moveDrag}
			onPointerUp={stopDrag}
		>
			<Resizable
				enable={enableResizing ? undefined : false}
				minHeight={minHeight}
				minWidth={minWidth}
				maxHeight={maxHeight}
				maxWidth={maxWidth}
				size={visualSize}
				style={{ overflow: 'visible' }}
				onResizeStart={() => {
					activity.current = 'resize';
					resizeOrigin.current = { ...visualPosition, ...visualSize };
					onResizeStart?.();
				}}
				onResize={(_event, direction, element) => {
					if (activity.current !== 'resize') return;
					const next = constrainResize(direction, { width: element.offsetWidth, height: element.offsetHeight });
					latestPosition.current = next;
					setVisualPosition({ x: next.x, y: next.y });
					setVisualSize({ width: next.width, height: next.height });
				}}
				onResizeStop={(_event, direction, element) => {
					if (activity.current !== 'resize') return;
					activity.current = undefined;
					const next = constrainResize(direction, { width: element.offsetWidth, height: element.offsetHeight });
					latestPosition.current = next;
					setVisualPosition({ x: next.x, y: next.y });
					setVisualSize({ width: next.width, height: next.height });
					onResizeStop?.(next);
				}}
			>
				{children}
			</Resizable>
		</div>
	);
}

export function getWindowManagerDragPosition(
	session: Pick<DragSession, 'maxX' | 'maxY' | 'minX' | 'minY' | 'originX' | 'originY' | 'startX' | 'startY'>,
	pointer: { x: number; y: number },
) {
	return {
		x: clamp(session.originX + pointer.x - session.startX, session.minX, session.maxX),
		y: clamp(session.originY + pointer.y - session.startY, session.minY, session.maxY),
	};
}

export function getWindowManagerConstrainedResize({
	bounds,
	direction,
	maxHeight,
	maxWidth,
	minHeight,
	minWidth,
	origin,
	requested,
}: {
	bounds: WindowManagerMotionBounds;
	direction: ResizeDirection;
	maxHeight: number;
	maxWidth: number;
	minHeight: number;
	minWidth: number;
	origin: WindowManagerMotionBounds;
	requested: { height: number; width: number };
}): WindowManagerMotionBounds {
	const value = direction.toLowerCase();
	const fromLeft = value.includes('left');
	const fromTop = value.includes('top');
	const horizontal = fromLeft || value.includes('right');
	const vertical = fromTop || value.includes('bottom');
	const fixedRight = origin.x + origin.width;
	const fixedBottom = origin.y + origin.height;
	const availableWidth = fromLeft ? fixedRight - bounds.x : bounds.x + bounds.width - origin.x;
	const availableHeight = fromTop ? fixedBottom - bounds.y : bounds.y + bounds.height - origin.y;
	const width = clamp(
		horizontal ? requested.width : origin.width,
		Math.min(minWidth, availableWidth),
		Math.min(maxWidth, availableWidth),
	);
	const height = clamp(
		vertical ? requested.height : origin.height,
		Math.min(minHeight, availableHeight),
		Math.min(maxHeight, availableHeight),
	);
	return {
		x: fromLeft ? fixedRight - width : origin.x,
		y: fromTop ? fixedBottom - height : origin.y,
		width,
		height,
	};
}

export function getWindowManagerResizePosition(
	origin: { x: number; y: number },
	direction: ResizeDirection,
	delta: { height: number; width: number },
) {
	return {
		x: origin.x - (direction.toLowerCase().includes('left') ? delta.width : 0),
		y: origin.y - (direction.toLowerCase().includes('top') ? delta.height : 0),
	};
}

function clamp(value: number, min: number, max: number) {
	return Math.min(Math.max(value, min), Math.max(min, max));
}

'use client';

import {
	type ComponentPropsWithRef,
	type KeyboardEvent as ReactKeyboardEvent,
	type ReactNode,
	type Ref,
	useEffect,
	useId,
	useRef,
	useState,
} from 'react';
import { createPortal } from 'react-dom';
import { useShallow } from 'zustand/react/shallow';
import { cn } from '@/lib/utils';
import {
	WINDOW_MANAGER_DRAG_HANDLE_CLASS,
	WindowManagerContent,
	WindowManagerControls,
	WindowManagerFrame,
	WindowManagerMenu,
	WindowManagerStatusBar,
	WindowManagerTitleBar,
	WindowManagerToolbar,
} from './window-manager-chrome';
import { useWindowManager } from './window-manager-context';
import { WINDOW_MANAGER_DOCK_Z_INDEX, WindowManagerDock, type WindowManagerDockProps } from './window-manager-dock';
import { WindowManagerMotionSurface } from './window-manager-motion';
import { getWindowManagerAvailableBounds, getWindowManagerRenderBounds } from './window-manager-store';
import type { ManagedWindow, WindowManagerActions, WindowManagerWorkspaceState } from './window-manager-types';

export type WindowManagerFrameRenderContext = {
	actions: Pick<
		WindowManagerActions,
		| 'close'
		| 'focus'
		| 'fullscreen'
		| 'maximize'
		| 'minimize'
		| 'restore'
		| 'setPinned'
		| 'toggleFullscreen'
		| 'toggleMaximize'
		| 'togglePinned'
	>;
	active: boolean;
	content: ReactNode;
	dragCancelProps: { 'data-window-drag-cancel': true };
	dragHandleProps: { className: string; 'data-window-drag-handle': true };
	icon?: ReactNode;
	menuItems?: ReactNode;
	overlayZIndex: number;
	statusBar?: ReactNode;
	titleId: string;
	toolbar?: ReactNode;
	win: ManagedWindow;
};

export type WindowManagerMenuRenderContext = {
	actions: WindowManagerActions;
	win: ManagedWindow;
};

export type WindowManagerHostProps = ComponentPropsWithRef<'div'> & {
	autoFocus?: boolean;
	background?: ReactNode;
	dock?: boolean | ReactNode;
	dockProps?: WindowManagerDockProps;
	keyboard?: boolean;
	renderContent?: (win: ManagedWindow) => ReactNode;
	renderFrame?: (context: WindowManagerFrameRenderContext) => ReactNode;
	renderIcon?: (win: ManagedWindow) => ReactNode;
	renderMenuItems?: (context: WindowManagerMenuRenderContext) => ReactNode;
	renderStatusBar?: (win: ManagedWindow) => ReactNode;
	renderToolbar?: (win: ManagedWindow) => ReactNode;
	unmountContentOnMinimize?: boolean;
	zIndexBase?: number;
};

export function WindowManagerHost({
	autoFocus = true,
	background,
	children,
	className,
	dock = true,
	dockProps,
	keyboard = true,
	onKeyDownCapture,
	ref,
	renderContent = defaultContent,
	renderFrame = defaultFrame,
	renderIcon,
	renderMenuItems,
	renderStatusBar,
	renderToolbar,
	unmountContentOnMinimize = false,
	zIndexBase = 20,
	...props
}: WindowManagerHostProps) {
	const rootRef = useRef<HTMLDivElement | null>(null);
	const { actions, activeId, order, windows, workspace } = useWindowManager(
		useShallow((state) => ({
			actions: state.actions,
			activeId: state.activeId,
			order: state.order,
			windows: state.windows,
			workspace: state.workspace,
		})),
	);

	useEffect(() => {
		if (typeof dock === 'boolean' && workspace.dock.visible !== dock) actions.setDock({ visible: dock });
	}, [actions, dock, workspace.dock.visible]);

	useEffect(() => {
		const element = rootRef.current;
		if (!element) return;
		const update = () => {
			const rect = element.getBoundingClientRect();
			if (rect.width > 0 && rect.height > 0) actions.setWorkspaceSize({ width: rect.width, height: rect.height });
		};
		update();
		if (typeof ResizeObserver !== 'undefined') {
			const observer = new ResizeObserver(update);
			observer.observe(element);
			return () => observer.disconnect();
		}
		window.addEventListener('resize', update);
		return () => window.removeEventListener('resize', update);
	}, [actions]);

	const handleKeyboard = (event: ReactKeyboardEvent<HTMLDivElement>) => {
		if (!keyboard) return;
		const active = activeId ? windows[activeId] : undefined;
		if (event.ctrlKey && event.key === 'F6') {
			event.preventDefault();
			actions.cycleFocus(event.shiftKey ? -1 : 1);
			return;
		}
		if (event.altKey && event.key === 'F9' && active) {
			event.preventDefault();
			actions.minimize(active.id);
			return;
		}
		if (event.altKey && event.key === 'F10' && active) {
			event.preventDefault();
			actions.toggleMaximize(active.id);
			return;
		}
		if (event.key === 'Escape' && active?.mode === 'fullscreen') {
			event.preventDefault();
			actions.restore(active.id);
			return;
		}
		if (
			!active ||
			!event.ctrlKey ||
			!event.altKey ||
			!event.key.startsWith('Arrow') ||
			isEditableTarget(event.target)
		) {
			return;
		}
		event.preventDefault();
		const step = event.shiftKey ? 24 : 10;
		const horizontal = event.key === 'ArrowLeft' ? -step : event.key === 'ArrowRight' ? step : 0;
		const vertical = event.key === 'ArrowUp' ? -step : event.key === 'ArrowDown' ? step : 0;
		if (event.shiftKey) actions.resizeBy(active.id, { width: horizontal, height: vertical });
		else actions.moveBy(active.id, { x: horizontal, y: vertical });
	};

	const hostWorkspace =
		dock === false && workspace.dock.visible
			? { ...workspace, dock: { ...workspace.dock, visible: false } }
			: workspace;

	return (
		<div
			{...props}
			ref={(element) => {
				rootRef.current = element;
				assignRef(ref, element);
			}}
			data-window-manager-host
			className={cn('bg-base-200 relative isolate h-full min-h-80 w-full overflow-hidden', className)}
			onKeyDownCapture={(event) => {
				onKeyDownCapture?.(event);
				if (!event.defaultPrevented) handleKeyboard(event);
			}}
		>
			{background}
			{children}
			{order.map((id, index) => {
				const win = windows[id];
				if (!win) return null;
				return (
					<ManagedWindowSurface
						key={id}
						actions={actions}
						active={activeId === id}
						autoFocus={autoFocus}
						index={index}
						overlayZIndex={Math.max(WINDOW_MANAGER_DOCK_Z_INDEX + 1, zIndexBase + order.length + 1)}
						renderContent={renderContent}
						renderFrame={renderFrame}
						renderIcon={renderIcon}
						renderMenuItems={renderMenuItems}
						renderStatusBar={renderStatusBar}
						renderToolbar={renderToolbar}
						unmountContentOnMinimize={unmountContentOnMinimize}
						win={win}
						workspace={hostWorkspace}
						zIndexBase={zIndexBase}
					/>
				);
			})}
			{dock === true ? (
				<WindowManagerDock
					menuZIndex={Math.max(WINDOW_MANAGER_DOCK_Z_INDEX + 1, zIndexBase + order.length + 1)}
					renderIcon={renderIcon}
					{...dockProps}
				/>
			) : (
				dock || null
			)}
		</div>
	);
}

export type WindowManagerPortalHostProps = Omit<WindowManagerHostProps, 'ref'> & {
	container?: Element | (() => Element | null) | null;
};

export function WindowManagerPortalHost({ container, className, ...props }: WindowManagerPortalHostProps) {
	const [target, setTarget] = useState<Element | null>(null);
	useEffect(() => {
		setTarget(typeof container === 'function' ? container() : (container ?? document.body));
	}, [container]);
	if (!target) return null;
	return createPortal(<WindowManagerHost className={cn('fixed inset-0 min-h-0', className)} {...props} />, target);
}

type ManagedWindowSurfaceProps = {
	actions: WindowManagerActions;
	active: boolean;
	autoFocus: boolean;
	index: number;
	overlayZIndex: number;
	renderContent: NonNullable<WindowManagerHostProps['renderContent']>;
	renderFrame: NonNullable<WindowManagerHostProps['renderFrame']>;
	renderIcon?: WindowManagerHostProps['renderIcon'];
	renderMenuItems?: WindowManagerHostProps['renderMenuItems'];
	renderStatusBar?: WindowManagerHostProps['renderStatusBar'];
	renderToolbar?: WindowManagerHostProps['renderToolbar'];
	unmountContentOnMinimize: boolean;
	win: ManagedWindow;
	workspace: WindowManagerWorkspaceState;
	zIndexBase: number;
};

function ManagedWindowSurface({
	actions,
	active,
	autoFocus,
	index,
	overlayZIndex,
	renderContent,
	renderFrame,
	renderIcon,
	renderMenuItems,
	renderStatusBar,
	renderToolbar,
	unmountContentOnMinimize,
	win,
	workspace,
	zIndexBase,
}: ManagedWindowSurfaceProps) {
	const surfaceRef = useRef<HTMLDivElement | null>(null);
	const titleId = useId();
	const minimized = win.mode === 'minimized';
	const bounds = getWindowManagerRenderBounds(win, workspace);
	const area = getWindowManagerAvailableBounds(workspace);
	const motionArea =
		win.mode === 'fullscreen' ? { x: 0, y: 0, width: workspace.width, height: workspace.height } : area;
	const movable = win.mode === 'normal' && win.capabilities.move;
	const resizable = win.mode === 'normal' && win.capabilities.resize;
	const content = minimized && unmountContentOnMinimize ? null : renderContent(win);
	const frame = renderFrame({
		win,
		active,
		content,
		dragCancelProps: { 'data-window-drag-cancel': true },
		dragHandleProps: {
			className: WINDOW_MANAGER_DRAG_HANDLE_CLASS,
			'data-window-drag-handle': true,
		},
		icon: renderIcon?.(win),
		menuItems: renderMenuItems?.({ actions, win }),
		overlayZIndex,
		toolbar: renderToolbar?.(win),
		statusBar: renderStatusBar?.(win),
		titleId,
		actions,
	});

	useEffect(() => {
		if (!autoFocus || !active || minimized || !surfaceRef.current) return;
		if (!surfaceRef.current.contains(document.activeElement)) surfaceRef.current.focus({ preventScroll: true });
	}, [active, autoFocus, minimized]);

	return (
		<WindowManagerMotionSurface
			cancel='[data-window-drag-cancel],button,input,textarea,select,a,[contenteditable="true"]'
			disableDragging={!movable}
			dragHandleClassName={WINDOW_MANAGER_DRAG_HANDLE_CLASS}
			enableResizing={resizable}
			interactionKey={win.mode}
			movementBounds={{ x: motionArea.x, y: motionArea.y, width: motionArea.width, height: motionArea.height }}
			maxHeight={Math.min(win.size.maxHeight ?? motionArea.height, motionArea.height)}
			maxWidth={Math.min(win.size.maxWidth ?? motionArea.width, motionArea.width)}
			minHeight={Math.min(win.size.minHeight, motionArea.height)}
			minWidth={Math.min(win.size.minWidth, motionArea.width)}
			position={{ x: bounds.x, y: bounds.y }}
			size={{ width: bounds.width, height: bounds.height }}
			style={{
				display: minimized ? 'none' : undefined,
				zIndex: zIndexBase + index,
			}}
			onMoveStart={() => {
				actions.focus(win.id);
			}}
			onMoveStop={(position) => {
				actions.setBounds(win.id, position, 'move');
			}}
			onResizeStart={() => {
				actions.focus(win.id);
			}}
			onResizeStop={(next) => {
				actions.setBounds(win.id, next, 'resize');
			}}
		>
			<div
				ref={surfaceRef}
				role='dialog'
				aria-label={win.title}
				aria-modal='false'
				tabIndex={-1}
				inert={minimized}
				data-window-id={win.id}
				data-window-mode={win.mode}
				data-window-pinned={win.pinned || undefined}
				className='size-full min-h-0 min-w-0 outline-none'
				onFocusCapture={() => {
					if (!active) actions.focus(win.id);
				}}
				onMouseDownCapture={() => {
					if (!active) actions.focus(win.id);
				}}
			>
				{frame}
			</div>
		</WindowManagerMotionSurface>
	);
}

function defaultFrame({
	actions,
	active,
	content,
	icon,
	menuItems,
	overlayZIndex,
	statusBar,
	titleId,
	toolbar,
	win,
}: WindowManagerFrameRenderContext) {
	if (win.chrome === 'none') {
		return (
			<div className={cn(WINDOW_MANAGER_DRAG_HANDLE_CLASS, 'bg-base-100 size-full overflow-auto rounded-sm shadow-lg')}>
				{content}
			</div>
		);
	}
	return (
		<WindowManagerFrame active={active} mode={win.mode}>
			<WindowManagerTitleBar
				id={titleId}
				icon={icon}
				title={win.title}
				onDoubleClick={(event) => {
					if (!win.capabilities.maximize || win.mode === 'fullscreen') return;
					if (event.target instanceof Element && event.target.closest('[data-window-drag-cancel]')) return;
					event.preventDefault();
					actions.toggleMaximize(win.id);
				}}
				controls={
					<WindowManagerControls
						menu={
							<WindowManagerMenu
								pinned={win.pinned}
								zIndex={overlayZIndex}
								onPinnedChange={(pinned) => actions.setPinned(win.id, pinned)}
							>
								{menuItems}
							</WindowManagerMenu>
						}
						mode={win.mode}
						canClose={win.capabilities.close}
						canFullscreen={win.capabilities.fullscreen}
						canMaximize={win.capabilities.maximize}
						canMinimize={win.capabilities.minimize}
						onClose={() => actions.close(win.id)}
						onFullscreen={() => actions.toggleFullscreen(win.id)}
						onMaximize={() => actions.toggleMaximize(win.id)}
						onMinimize={() => actions.minimize(win.id)}
					/>
				}
			/>
			{toolbar ? <WindowManagerToolbar>{toolbar}</WindowManagerToolbar> : null}
			<WindowManagerContent>{content}</WindowManagerContent>
			{statusBar ? <WindowManagerStatusBar>{statusBar}</WindowManagerStatusBar> : null}
		</WindowManagerFrame>
	);
}

function defaultContent(win: ManagedWindow) {
	return (
		<div className='grid min-h-full place-items-center p-6 text-center'>
			<div>
				<div className='font-medium'>{win.title}</div>
				<div className='text-base-content/60 mt-1 text-sm'>Register a renderer for “{win.kind}”.</div>
			</div>
		</div>
	);
}

function isEditableTarget(target: EventTarget | null) {
	return (
		target instanceof HTMLElement &&
		(target.isContentEditable ||
			target instanceof HTMLInputElement ||
			target instanceof HTMLTextAreaElement ||
			target instanceof HTMLSelectElement)
	);
}

function assignRef<T>(ref: Ref<T> | undefined, value: T | null) {
	if (typeof ref === 'function') ref(value);
	else if (ref) ref.current = value;
}

'use client';

import { useEffect, useRef } from 'react';
import { useWindowManagerApi } from './window-manager-context';
import { isWindowManagerSnapshot } from './window-manager-store';
import type {
	ManagedWindow,
	WindowManagerSnapshot,
	WindowManagerState,
	WindowManagerStorage,
} from './window-manager-types';
import { WINDOW_MANAGER_SNAPSHOT_VERSION } from './window-manager-types';

export type WindowManagerPersistenceProps = {
	debounceMs?: number;
	migrate?: (value: unknown) => WindowManagerSnapshot | undefined;
	onError?: (error: Error) => void;
	restoreMinimized?: boolean;
	serializeData?: (win: ManagedWindow) => unknown;
	storage?: 'local' | 'session' | WindowManagerStorage;
	storageKey?: string;
};

export function WindowManagerPersistence({
	debounceMs = 180,
	migrate,
	onError,
	restoreMinimized = false,
	serializeData,
	storage = 'local',
	storageKey = 'window-manager.layout.v1',
}: WindowManagerPersistenceProps) {
	const store = useWindowManagerApi();
	const optionsRef = useRef({ debounceMs, migrate, onError, restoreMinimized, serializeData });
	optionsRef.current = { debounceMs, migrate, onError, restoreMinimized, serializeData };

	useEffect(() => {
		const target = resolveStorage(storage);
		if (!target) {
			store.getState().actions.setHydration({ status: 'ready' });
			return;
		}
		let timer: ReturnType<typeof setTimeout> | undefined;
		let disposed = false;
		let writesDisabled = false;
		const report = (value: unknown) => {
			const error = value instanceof Error ? value : new Error('Window layout persistence failed');
			store.getState().actions.setHydration({ status: 'error', error: error.message });
			optionsRef.current.onError?.(error);
		};

		store.getState().actions.setHydration({ status: 'hydrating' });
		try {
			const raw = target.getItem(storageKey);
			if (raw) {
				const value: unknown = JSON.parse(raw);
				const snapshot = isWindowManagerSnapshot(value) ? value : optionsRef.current.migrate?.(value);
				if (!snapshot || !isWindowManagerSnapshot(snapshot))
					throw new Error('Stored window layout has an unsupported shape');
				if (
					!store.getState().actions.hydrateLayout(snapshot, { restoreMinimized: optionsRef.current.restoreMinimized })
				) {
					throw new Error('Stored window layout could not be restored');
				}
			} else {
				store.getState().actions.setHydration({ status: 'ready' });
			}
		} catch (error) {
			report(error);
		}

		const save = () => {
			if (disposed || writesDisabled) return;
			try {
				target.setItem(
					storageKey,
					JSON.stringify(
						createWindowManagerSnapshot(store.getState(), { serializeData: optionsRef.current.serializeData }),
					),
				);
			} catch (error) {
				writesDisabled = true;
				report(error);
			}
		};
		const unsubscribe = store.subscribe(() => {
			if (writesDisabled) return;
			if (timer) clearTimeout(timer);
			timer = setTimeout(save, Math.max(0, optionsRef.current.debounceMs));
		});
		return () => {
			disposed = true;
			unsubscribe();
			if (timer) clearTimeout(timer);
		};
	}, [storage, storageKey, store]);

	return null;
}

export function createWindowManagerSnapshot(
	state: WindowManagerState,
	options: { now?: () => number; serializeData?: (win: ManagedWindow) => unknown } = {},
): WindowManagerSnapshot {
	const windows = state.dockOrder.flatMap((id) => {
		const win = state.windows[id];
		if (!win || win.persistence === 'none') return [];
		const data = options.serializeData?.(win);
		return [
			{
				id: win.id,
				key: win.key,
				kind: win.kind,
				title: win.title,
				icon: win.icon,
				bounds: { ...win.bounds },
				size: { ...win.size },
				capabilities: { ...win.capabilities },
				mode: win.mode,
				restoreMode: win.restoreMode,
				fullscreenRestoreMode: win.fullscreenRestoreMode,
				chrome: win.chrome,
				showInDock: win.showInDock,
				persistence: win.persistence,
				pinned: win.pinned,
				...(data === undefined ? {} : { data }),
			},
		];
	});
	const persistentIds = new Set(windows.map((win) => win.id));
	return {
		version: WINDOW_MANAGER_SNAPSHOT_VERSION,
		savedAt: (options.now ?? Date.now)(),
		dock: { ...state.workspace.dock },
		dockOrder: windows.map((win) => win.id),
		order: state.order.filter((id) => persistentIds.has(id)),
		windows,
	};
}

function resolveStorage(storage: WindowManagerPersistenceProps['storage']): WindowManagerStorage | undefined {
	if (typeof storage === 'object') return storage;
	if (typeof window === 'undefined') return undefined;
	return storage === 'session' ? window.sessionStorage : window.localStorage;
}

'use client';

import { WindowManagerProvider } from './window-manager-context';
import { WindowManagerHost, type WindowManagerHostProps } from './window-manager-host';
import { WindowManagerPersistence, type WindowManagerPersistenceProps } from './window-manager-persistence';
import type { WindowManagerStore } from './window-manager-store';
import type { WindowManagerCreateOptions } from './window-manager-types';

export type WindowManagerRuntimeProps = WindowManagerHostProps & {
	options?: WindowManagerCreateOptions;
	persistence?: false | WindowManagerPersistenceProps;
	store?: WindowManagerStore;
};

export function WindowManagerRuntime({ options, persistence = false, store, ...hostProps }: WindowManagerRuntimeProps) {
	return (
		<WindowManagerProvider options={options} store={store}>
			{persistence ? <WindowManagerPersistence {...persistence} /> : null}
			<WindowManagerHost {...hostProps} />
		</WindowManagerProvider>
	);
}

